      type: 'number',
      displayName: 'Seed',
      group: 'Configuration',
      default: null,
      set: function (value) {
        try {
          if (value === null || value === undefined || value === '') {
            this._internal.seed = null;
          } else {
            this._internal.seed = validateNumberInput(value);
          }
          // Reset ISAAC instance when seed changes
          this._internal.isaac = null;
          this._internal.lastError = null;
